import{_ as e,o as r,c as a,ah as d}from"./chunks/framework.C-FRNfAJ.js";const p=JSON.parse('{"title":"Comptes et rôles","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/roles.md","filePath":"src/guide/roles.md"}'),n={name:"guide/roles.md"};function o(s,t,i,l,u,c){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="comptes-et-roles" tabindex="-1">Comptes et rôles <a class="header-anchor" href="#comptes-et-roles" aria-label="Permalink to &quot;Comptes et rôles&quot;">​</a></h1><p>Kura ne connaît qu&#39;<strong>un seul compte par personne</strong>, identifié par son email. Un compte cumule des rôles au fil du temps ; on ne recrée jamais de compte, même après une transformation en organisation.</p><h2 id="le-compte-nextboxx" tabindex="-1">Le compte NextBoxx <a class="header-anchor" href="#le-compte-nextboxx" aria-label="Permalink to &quot;Le compte NextBoxx&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Attribut</th><th>Valeurs</th></tr></thead><tbody><tr><td>Type</td><td><code>individu</code> ou <code>organisation</code></td></tr><tr><td>Statut global</td><td><code>actif</code>, <code>suspendu</code> (impayé), <code>canope</code> (certifié)</td></tr><tr><td>Identifiant</td><td>email, sans tenir compte de la casse</td></tr><tr><td>Désactivation</td><td>automatique un an après la dernière connexion, données conservées</td></tr></tbody></table><p>Un compte <strong>organisation</strong> naît uniquement de la transformation d&#39;un compte individu, validée par l&#39;Administrateur. L&#39;historique individuel (formations, statut Canopé) reste consultable en lecture seule ; la raison sociale devient le nom du compte et l&#39;ancien nom reste dans la demande et le journal.</p><p>Le statut <code>suspendu</code> bloque toute action payante, quel que soit le module. Le statut <code>canope</code> est attribué à la délivrance du certificat.</p><h2 id="les-roles" tabindex="-1">Les rôles <a class="header-anchor" href="#les-roles" aria-label="Permalink to &quot;Les rôles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rôle</th><th>Attribué par</th><th>Périmètre</th></tr></thead><tbody><tr><td><strong>Candidat</strong></td><td>Automatique au dépôt</td><td>Passer le test, suivre son dossier</td></tr><tr><td><strong>Participant</strong></td><td>Automatique à l&#39;inscription à un événement</td><td>S&#39;inscrire aux événements, aucun accès formation</td></tr><tr><td><strong>Apprenant</strong></td><td>Automatique à l&#39;admission</td><td>Signer, payer, consulter ses documents, suivre sa formation sur Sève, se rendre visible des entreprises une fois certifié</td></tr><tr><td><strong>Formateur Principal</strong></td><td>Coordinateur pédagogique</td><td>Ses cohortes, sa rémunération, la présence en présentiel, les repêchages ; aucun accès à la banque QCM</td></tr><tr><td><strong>Coach-Tuteur</strong></td><td>Coordinateur pédagogique</td><td>Ses apprenants suivis, sa rémunération, son espace Sève</td></tr><tr><td><strong>Coordinateur pédagogique</strong></td><td>Administrateur</td><td>Catalogue, QCM, cohortes, inscriptions, facturation, certification, rémunérations, annonces, RGPD</td></tr><tr><td><strong>Conseiller admissions</strong></td><td>Administrateur</td><td>Instruction des candidatures : entretien, relance du test, décision motivée</td></tr><tr><td><strong>Apporteur d&#39;affaires</strong></td><td>Chargé de partenariats</td><td>Inscriptions apportées et commissions</td></tr><tr><td><strong>Partenaire marketing</strong></td><td>Chargé de partenariats</td><td>Dépôt de factures et suivi du paiement</td></tr><tr><td><strong>Financeur</strong></td><td>Chargé de partenariats</td><td>Espace financeur : apprenants financés, progression simplifiée, factures de sa part</td></tr><tr><td><strong>Financeur d&#39;événement</strong></td><td>Chargé d&#39;événements</td><td>Déclaration d&#39;apports et espace de financement</td></tr><tr><td><strong>Porteur de projet</strong></td><td>Chargé d&#39;incubation, à la rétention</td><td>Suivi de son projet L&#39;Éclosion et de sa participation</td></tr><tr><td><strong>Chargé d&#39;événements</strong></td><td>Administrateur</td><td>Module événements et validation des rôles associés</td></tr><tr><td><strong>Chargé de partenariats</strong></td><td>Administrateur</td><td>Mise en relation, recrutement, partenariats marketing et technologiques</td></tr><tr><td><strong>Chargé d&#39;incubation</strong></td><td>Administrateur</td><td>Module L&#39;Éclosion et validation des porteurs</td></tr><tr><td><strong>Direction</strong></td><td>Administrateur</td><td>Tableau de bord consolidé en lecture seule, comité d&#39;investissement</td></tr><tr><td><strong>Administrateur</strong></td><td>Administrateur</td><td>Transformation de compte, rôles à privilèges, journaux, régénération du token Sève</td></tr></tbody></table><p>Trois rôles sont attribués par le système à un événement métier : Candidat, Participant et Apprenant. Tous les autres passent par une demande validée par l&#39;acteur désigné — jamais automatiquement.</p><h2 id="roles-demandables" tabindex="-1">Rôles demandables <a class="header-anchor" href="#roles-demandables" aria-label="Permalink to &quot;Rôles demandables&quot;">​</a></h2><p>Depuis ses paramètres, un compte peut demander :</p><ul><li>Formateur Principal</li><li>Coach-Tuteur</li><li>Apporteur d&#39;affaires</li><li>Partenaire marketing</li><li>Financeur (compte organisation obligatoire)</li><li>Financeur d&#39;événement</li></ul><p>Les rôles d&#39;état-major (Coordinateur, Conseillers, Chargés, Direction, Administrateur) sont attribués directement par l&#39;Administrateur.</p><h2 id="regles-de-validation" tabindex="-1">Règles de validation <a class="header-anchor" href="#regles-de-validation" aria-label="Permalink to &quot;Règles de validation&quot;">​</a></h2><ul><li>L&#39;Administrateur peut valider <strong>tous</strong> les rôles, en plus de l&#39;acteur désigné, pour qu&#39;aucune demande ne reste bloquée par un poste vacant.</li><li>Personne ne décide de sa propre demande et personne ne retire son propre rôle.</li><li>Un rôle refusé n&#39;est jamais activé ; les rôles existants restent intacts.</li><li>Le rôle Financeur exige un compte organisation ; le Financeur d&#39;événement reste ouvert aux comptes individu.</li><li>Les actions des comptes à privilèges (Coordinateur pédagogique, Direction, Administrateur) sur les comptes et les rôles sont journalisées avec l&#39;acteur et l&#39;horodatage.</li></ul><h2 id="autorisations-techniques" tabindex="-1">Autorisations techniques <a class="header-anchor" href="#autorisations-techniques" aria-label="Permalink to &quot;Autorisations techniques&quot;">​</a></h2><p>Les Gates sont définis dans <code>AppServiceProvider</code> et consommés par les routes (<code>can:*</code>), les contrôleurs (<code>Gate::authorize</code>) et le front (<code>useAccess</code>).</p><table tabindex="0"><thead><tr><th>Gate</th><th>Usage</th></tr></thead><tbody><tr><td><code>approve-roles</code></td><td>Instruction des demandes de rôle</td></tr><tr><td><code>view-candidatures</code></td><td>File et dossiers de candidature</td></tr><tr><td><code>manage-catalogue</code></td><td>Référentiels, grille tarifaire, banque QCM</td></tr><tr><td><code>view-cohorts</code>, <code>manage-cohorts</code></td><td>Consultation et pilotage des cohortes</td></tr><tr><td><code>manage-enrolments</code></td><td>Inscriptions, placements, consentements</td></tr><tr><td><code>manage-billing</code></td><td>Factures, paiements, avoirs, relances</td></tr><tr><td><code>view-funded-learners</code></td><td>Espace financeur</td></tr><tr><td><code>view-own-commissions</code>, <code>view-own-remuneration</code></td><td>Espaces personnels apporteur et formateur</td></tr><tr><td><code>submit-marketing-invoices</code></td><td>Dépôt de factures marketing</td></tr><tr><td><code>view-direction-dashboard</code></td><td>Tableau de bord Direction</td></tr><tr><td><code>view-reporting</code></td><td>Reporting et exports</td></tr><tr><td><code>manage-communication</code></td><td>Annonces et journal des envois</td></tr><tr><td><code>manage-events</code>, <code>manage-company-requests</code></td><td>Modules événements et demandes entreprises</td></tr><tr><td><code>manage-incubation</code>, <code>sit-investment-committee</code></td><td>L&#39;Éclosion et comité d&#39;investissement</td></tr><tr><td><code>manage-tech-partnerships</code></td><td>Partenariats technologiques</td></tr></tbody></table><h2 id="parcours-d-une-demande-de-role" tabindex="-1">Parcours d&#39;une demande de rôle <a class="header-anchor" href="#parcours-d-une-demande-de-role" aria-label="Permalink to &quot;Parcours d&#39;une demande de rôle&quot;">​</a></h2><ol><li>Le titulaire dépose une demande depuis ses paramètres (ou l&#39;Administrateur crée le compte).</li><li>L&#39;acteur désigné — ou l&#39;Administrateur — instruit la demande.</li><li>Il valide ou refuse en motivant.</li><li>Le titulaire est notifié ; un rôle validé se cumule aux rôles existants.</li></ol><p>Voir aussi <a href="/kura-guide/guide/learner-journey.html">Parcours apprenant</a> et <a href="/kura-guide/guide/core-modules.html">Modules du socle</a>.</p>',21)])])}const g=e(n,[["render",o]]);export{p as __pageData,g as default};
